// Simple PRNG - xorshift64* - for nonsense generation
use std::cell::Cell;

pub struct Rng {
    state: Cell<u64>,
}

impl Rng {
    pub fn new() -> Self {
        use std::time::{SystemTime, UNIX_EPOCH};
        let seed = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0x12345678deadbeef)
            .wrapping_mul(0x9e3779b97f4a7c15)
            ^ std::process::id() as u64;
        Self { state: Cell::new(if seed == 0 { 1 } else { seed }) }
    }

    pub fn next_u64(&self) -> u64 {
        let mut x = self.state.get();
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.state.set(x);
        x
    }

    pub fn gen_range_u64(&self, min: u64, max_excl: u64) -> u64 {
        if max_excl <= min { return min; }
        min + self.next_u64() % (max_excl - min)
    }

    pub fn gen_range_usize(&self, min: usize, max_excl: usize) -> usize {
        self.gen_range_u64(min as u64, max_excl as u64) as usize
    }

    pub fn gen_range_i64(&self, min: i64, max_excl: i64) -> i64 {
        if max_excl <= min { return min; }
        let span = (max_excl - min) as u64;
        min + (self.next_u64() % span) as i64
    }

    pub fn gen_f64(&self) -> f64 {
        (self.next_u64() >> 11) as f64 * (1.0 / ((1u64 << 53) as f64))
    }

    pub fn bool_with_prob(&self, p: f64) -> bool {
        self.gen_f64() < p
    }

    pub fn choose<'a, T>(&self, items: &'a [T]) -> &'a T {
        &items[self.gen_range_usize(0, items.len())]
    }

    pub fn choose_str<'a>(&self, items: &'a [&'a str]) -> &'a str {
        items[self.gen_range_usize(0, items.len())]
    }

    pub fn shuffle<T>(&self, items: &mut [T]) {
        let n = items.len();
        for i in (1..n).rev() {
            let j = self.gen_range_usize(0, i + 1);
            items.swap(i, j);
        }
    }

    pub fn hex_string(&self, len: usize) -> String {
        let chars = "0123456789abcdef";
        let bytes = chars.as_bytes();
        (0..len).map(|_| bytes[self.gen_range_usize(0, 16)] as char).collect()
    }

    pub fn hex_string_upper(&self, len: usize) -> String {
        let chars = "0123456789ABCDEF";
        let bytes = chars.as_bytes();
        (0..len).map(|_| bytes[self.gen_range_usize(0, 16)] as char).collect()
    }

    pub fn alpha_string(&self, len: usize) -> String {
        let chars = "abcdefghijklmnopqrstuvwxyz";
        let bytes = chars.as_bytes();
        (0..len).map(|_| bytes[self.gen_range_usize(0, 26)] as char).collect()
    }

    pub fn alphanum_string(&self, len: usize) -> String {
        let chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        let bytes = chars.as_bytes();
        (0..len).map(|_| bytes[self.gen_range_usize(0, 62)] as char).collect()
    }
}
EOF
