// CLI argument parsing, mimicking clap's output formatting

use std::process::ExitCode;

pub const VERSION: &str = "1.5.1";
pub const ABOUT: &str = "A nonsense activity generator";
pub const AUTHOR: &str = "Sven-Hendrik Haase <svenstaro@gmail.com>";

pub const ALL_MODULES: &[&str] = &[
    "ansible", "bootlog", "botnet", "bruteforce", "cargo", "cc", "composer",
    "cryptomining", "docker_build", "docker_image_rm", "download", "julia",
    "kernel_compile", "memdump", "mkinitcpio", "rkhunter", "simcity",
    "terraform", "uv", "weblog", "wpt",
];

pub const SHELLS: &[&str] = &["bash", "elvish", "fish", "powershell", "zsh"];

#[derive(Debug, Clone, Default)]
pub struct Args {
    pub list_modules: bool,
    pub modules: Vec<String>,
    pub speed_factor: f64,
    pub instant_print_lines: u64,
    pub inhibit: bool,
    pub exit_after_time: Option<String>,
    pub exit_after_modules: Option<u64>,
    pub print_completions: Option<String>,
    pub print_manpage: bool,
}

pub enum ParseResult {
    Ok(Args),
    // exit with given code after printing already
    Exit(i32),
}

fn bin_name() -> String {
    std::env::args().next()
        .and_then(|s| {
            std::path::Path::new(&s)
                .file_name()
                .and_then(|os| os.to_str())
                .map(|s| s.to_string())
        })
        .unwrap_or_else(|| "genact".to_string())
}

fn usage_line() -> String {
    format!("Usage: {} [OPTIONS]", bin_name())
}

fn print_error_usage(msg: &str) {
    eprintln!("error: {}", msg);
    eprintln!();
    eprintln!("{}", usage_line());
    eprintln!();
    eprintln!("For more information, try '--help'.");
}

fn print_error_no_usage(msg: &str) {
    eprintln!("error: {}", msg);
    eprintln!();
    eprintln!("For more information, try '--help'.");
}

fn print_error_value_with_possible(value: &str, opt: &str, possible: &[&str]) {
    eprintln!("error: invalid value '{}' for '{}'", value, opt);
    eprintln!("  [possible values: {}]", possible.join(", "));
    eprintln!();
    eprintln!("For more information, try '--help'.");
}

fn possible_values_line(vals: &[&str]) -> String {
    vals.join(", ")
}

pub fn print_help() {
    let bn = bin_name();
    let out = format!(
"A nonsense activity generator

Usage: {bn} [OPTIONS]

Options:
  -l, --list-modules
          List available modules
  -m, --modules <MODULES>
          Run only these modules [possible values: ansible, bootlog, botnet, bruteforce, cargo, cc,
          composer, cryptomining, docker_build, docker_image_rm, download, julia, kernel_compile,
          memdump, mkinitcpio, rkhunter, simcity, terraform, uv, weblog, wpt]
  -s, --speed-factor <SPEED_FACTOR>
          Global speed factor [default: 1]
  -i, --instant-print-lines <INSTANT_PRINT_LINES>
          Instantly print this many lines [default: 0]
      --inhibit
          Keep the computer awake and the display on while genact is running
      --exit-after-time <EXIT_AFTER_TIME>
          Exit after running for this long (format example: 2h10min)
      --exit-after-modules <EXIT_AFTER_MODULES>
          Exit after running this many modules
      --print-completions <shell>
          Generate completion file for a shell [possible values: bash, elvish, fish, powershell,
          zsh]
      --print-manpage
          Generate man page
  -h, --help
          Print help
  -V, --version
          Print version
",
        bn = bn);
    print!("{}", out);
}

pub fn print_version() {
    println!("genact {}", VERSION);
}

pub fn print_list_modules() {
    println!("Available modules:");
    for m in ALL_MODULES {
        println!("  {}", m);
    }
}

pub fn parse() -> ParseResult {
    let raw_args: Vec<String> = std::env::args().skip(1).collect();
    let mut args = Args {
        speed_factor: 1.0,
        instant_print_lines: 0,
        ..Default::default()
    };

    let mut i = 0;
    while i < raw_args.len() {
        let a = &raw_args[i];
        match a.as_str() {
            "-h" | "--help" => {
                print_help();
                return ParseResult::Exit(0);
            }
            "-V" | "--version" => {
                print_version();
                return ParseResult::Exit(0);
            }
            "-l" | "--list-modules" => {
                args.list_modules = true;
                i += 1;
            }
            "--inhibit" => {
                args.inhibit = true;
                i += 1;
            }
            "--print-manpage" => {
                args.print_manpage = true;
                i += 1;
            }
            "-m" | "--modules" => {
                if i + 1 >= raw_args.len() {
                    eprintln!("error: a value is required for '--modules <MODULES>' but none was supplied");
                    eprintln!("  [possible values: {}]", possible_values_line(ALL_MODULES));
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    return ParseResult::Exit(2);
                }
                let v = &raw_args[i + 1];
                if !ALL_MODULES.contains(&v.as_str()) {
                    print_error_value_with_possible(v, "--modules <MODULES>", ALL_MODULES);
                    return ParseResult::Exit(2);
                }
                args.modules.push(v.clone());
                i += 2;
            }
            s if s.starts_with("--modules=") => {
                let v = &s["--modules=".len()..];
                if !ALL_MODULES.contains(&v) {
                    print_error_value_with_possible(v, "--modules <MODULES>", ALL_MODULES);
                    return ParseResult::Exit(2);
                }
                args.modules.push(v.to_string());
                i += 1;
            }
            "-s" | "--speed-factor" => {
                if i + 1 >= raw_args.len() {
                    eprintln!("error: a value is required for '--speed-factor <SPEED_FACTOR>' but none was supplied");
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    return ParseResult::Exit(2);
                }
                let v = &raw_args[i + 1];
                match v.parse::<f64>() {
                    Ok(n) => {
                        if n < 0.01 {
                            print_error_no_usage(&format!(
                                "invalid value '{}' for '--speed-factor <SPEED_FACTOR>': Speed factor must be larger than 0.01",
                                v));
                            return ParseResult::Exit(2);
                        }
                        args.speed_factor = n;
                    }
                    Err(_) => {
                        print_error_no_usage(&format!(
                            "invalid value '{}' for '--speed-factor <SPEED_FACTOR>': invalid float literal",
                            v));
                        return ParseResult::Exit(2);
                    }
                }
                i += 2;
            }
            s if s.starts_with("--speed-factor=") => {
                let v = &s["--speed-factor=".len()..];
                match v.parse::<f64>() {
                    Ok(n) => {
                        if n < 0.01 {
                            print_error_no_usage(&format!(
                                "invalid value '{}' for '--speed-factor <SPEED_FACTOR>': Speed factor must be larger than 0.01",
                                v));
                            return ParseResult::Exit(2);
                        }
                        args.speed_factor = n;
                    }
                    Err(_) => {
                        print_error_no_usage(&format!(
                            "invalid value '{}' for '--speed-factor <SPEED_FACTOR>': invalid float literal",
                            v));
                        return ParseResult::Exit(2);
                    }
                }
                i += 1;
            }
            "-i" | "--instant-print-lines" => {
                if i + 1 >= raw_args.len() {
                    eprintln!("error: a value is required for '--instant-print-lines <INSTANT_PRINT_LINES>' but none was supplied");
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    return ParseResult::Exit(2);
                }
                let v = &raw_args[i + 1];
                match v.parse::<u64>() {
                    Ok(n) => { args.instant_print_lines = n; }
                    Err(_) => {
                        print_error_no_usage(&format!(
                            "invalid value '{}' for '--instant-print-lines <INSTANT_PRINT_LINES>': invalid digit found in string",
                            v));
                        return ParseResult::Exit(2);
                    }
                }
                i += 2;
            }
            s if s.starts_with("--instant-print-lines=") => {
                let v = &s["--instant-print-lines=".len()..];
                match v.parse::<u64>() {
                    Ok(n) => { args.instant_print_lines = n; }
                    Err(_) => {
                        print_error_no_usage(&format!(
                            "invalid value '{}' for '--instant-print-lines <INSTANT_PRINT_LINES>': invalid digit found in string",
                            v));
                        return ParseResult::Exit(2);
                    }
                }
                i += 1;
            }
            "--exit-after-time" => {
                if i + 1 >= raw_args.len() {
                    eprintln!("error: a value is required for '--exit-after-time <EXIT_AFTER_TIME>' but none was supplied");
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    return ParseResult::Exit(2);
                }
                let v = &raw_args[i + 1];
                match crate::duration::parse_duration_msg(v) {
                    Ok(_) => { args.exit_after_time = Some(v.clone()); }
                    Err(msg) => {
                        print_error_no_usage(&format!(
                            "invalid value '{}' for '--exit-after-time <EXIT_AFTER_TIME>': {}",
                            v, msg));
                        return ParseResult::Exit(2);
                    }
                }
                i += 2;
            }
            s if s.starts_with("--exit-after-time=") => {
                let v = &s["--exit-after-time=".len()..];
                match crate::duration::parse_duration_msg(v) {
                    Ok(_) => { args.exit_after_time = Some(v.to_string()); }
                    Err(msg) => {
                        print_error_no_usage(&format!(
                            "invalid value '{}' for '--exit-after-time <EXIT_AFTER_TIME>': {}",
                            v, msg));
                        return ParseResult::Exit(2);
                    }
                }
                i += 1;
