// Simple duration parser mimicking the `humantime`-style format errors shown by the binary.
// Supported units: ns, us, µs, ms, sec, min, hours, days, weeks, months, years + variations

pub fn parse_duration_msg(s: &str) -> Result<std::time::Duration, String> {
    let s = s.trim();
    if s.is_empty() {
        return Err("value was empty".to_string());
    }

    let mut total_nanos: u128 = 0;
    let bytes = s.as_bytes();
    let mut i = 0usize;

    loop {
        while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t') {
            i += 1;
        }
        if i >= bytes.len() {
            break;
        }

        let num_start = i;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
        }
        if i == num_start {
            return Err(format!("expected number at {}", num_start));
        }
        let num_str = &s[num_start..i];
        let num: u128 = num_str.parse().map_err(|_| "number too large".to_string())?;

        while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t') {
            i += 1;
        }

        // parse unit (greedy alpha)
        let unit_start = i;
        // Allow µ (non-ascii)
        while i < bytes.len() {
            let c = bytes[i];
            if c.is_ascii_alphabetic() {
                i += 1;
            } else if c >= 0x80 {
                // accept up to 2 bytes for µ
                i += 1;
            } else {
                break;
            }
        }
        if i == unit_start {
            return Err(format!("expected units after number, found end of string"));
        }
        let unit = &s[unit_start..i];
        let nanos_per_unit: u128 = match unit {
            "ns" | "nsec" => 1,
            "us" | "usec" | "µs" => 1_000,
            "ms" | "msec" => 1_000_000,
            "s" | "sec" | "secs" | "second" | "seconds" => 1_000_000_000,
            "m" | "min" | "mins" | "minute" | "minutes" => 60 * 1_000_000_000,
            "h" | "hr" | "hrs" | "hour" | "hours" => 3_600 * 1_000_000_000,
            "d" | "day" | "days" => 86_400 * 1_000_000_000,
            "w" | "week" | "weeks" => 7 * 86_400 * 1_000_000_000,
            "M" | "month" | "months" => 2_630_016 * 1_000_000_000,
            "y" | "year" | "years" => 31_557_600 * 1_000_000_000,
            other => {
                return Err(format!("unknown time unit \"{}\", supported units: ns, us/µs, ms, sec, min, hours, days, weeks, months, years (and few variations)", other));
            }
        };
        total_nanos = total_nanos.saturating_add(num.saturating_mul(nanos_per_unit));
    }

    let secs = (total_nanos / 1_000_000_000) as u64;
    let nanos = (total_nanos % 1_000_000_000) as u32;
    Ok(std::time::Duration::new(secs, nanos))
}
