// Helpers for printing output, sleeping, instant-print, and exit behavior.
use std::io::Write;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::OnceLock;
use std::time::{Duration, Instant};

static INSTANT_LINES: AtomicU64 = AtomicU64::new(0);
static SPEED_FACTOR_BITS: AtomicU64 = AtomicU64::new(0);
static SHOULD_EXIT: AtomicBool = AtomicBool::new(false);
static DEADLINE: OnceLock<Option<Instant>> = OnceLock::new();

pub fn set_instant_lines(n: u64) {
    INSTANT_LINES.store(n, Ordering::Relaxed);
}
pub fn set_speed_factor(f: f64) {
    SPEED_FACTOR_BITS.store(f.to_bits(), Ordering::Relaxed);
}
pub fn speed_factor() -> f64 {
    let bits = SPEED_FACTOR_BITS.load(Ordering::Relaxed);
    if bits == 0 { 1.0 } else { f64::from_bits(bits) }
}
pub fn set_deadline(d: Option<Instant>) {
    let _ = DEADLINE.set(d);
}
pub fn should_exit() -> bool {
    if SHOULD_EXIT.load(Ordering::Relaxed) { return true; }
    if let Some(Some(d)) = DEADLINE.get() {
        if Instant::now() >= *d { return true; }
    }
    false
}
pub fn request_exit() {
    SHOULD_EXIT.store(true, Ordering::Relaxed);
}

pub fn consume_instant_line() -> bool {
    let mut cur = INSTANT_LINES.load(Ordering::Relaxed);
    while cur > 0 {
        match INSTANT_LINES.compare_exchange(cur, cur - 1, Ordering::Relaxed, Ordering::Relaxed) {
            Ok(_) => return true,
            Err(x) => cur = x,
        }
    }
    false
}

pub fn sleep_ms(ms: u64) {
    if consume_instant_line() { return; }
    let factor = speed_factor();
    if factor <= 0.0 { return; }
    let scaled = (ms as f64 / factor).round() as u64;
    if scaled == 0 { return; }
    let total = Duration::from_millis(scaled);
    let start = Instant::now();
    let step = Duration::from_millis(20);
    while start.elapsed() < total {
        if should_exit() { return; }
        let remaining = total - start.elapsed();
        std::thread::sleep(std::cmp::min(remaining, step));
    }
}

pub fn print_line(s: &str) {
    println!("{}", s);
    let _ = std::io::stdout().flush();
}

pub fn print_str(s: &str) {
    print!("{}", s);
    let _ = std::io::stdout().flush();
}

pub fn csleep(ms: u64) { sleep_ms(ms); }

pub fn newline() {
    println!();
    let _ = std::io::stdout().flush();
}

pub fn cursor_up_clear() {
    // Move cursor up and clear line
    print!("\x1b[A\x1b[K");
    let _ = std::io::stdout().flush();
}
EOF
