    let total = Duration::from_millis(scaled);
    let start = Instant::now();
    let step = Duration::from_millis(20);
    while start.elapsed() < total {
        if should_exit() { return; }
        let remaining = total - start.elapsed();
        std::thread::sleep(std::cmp::min(remaining, step));
    }
}

pub fn print_line(s: &str) {
    println!("{}", s);
    let _ = std::io::stdout().flush();
}

pub fn print_str(s: &str) {
    print!("{}", s);
    let _ = std::io::stdout().flush();
}

pub fn csleep(ms: u64) { sleep_ms(ms); }

pub fn newline() {
    println!();
    let _ = std::io::stdout().flush();
}

pub fn cursor_up_clear() {
    // Move cursor up and clear line
    print!("\x1b[A\x1b[K");
    let _ = std::io::stdout().flush();
}
