use crate::data::*;
use crate::io::{csleep, print_line, should_exit};
use crate::rng::Rng;

fn pick_n<'a>(rng: &Rng, pool: &'a [&'a str], n: usize) -> Vec<&'a str> {
    let mut idxs: Vec<usize> = (0..pool.len()).collect();
    rng.shuffle(&mut idxs);
    idxs.into_iter().take(n).map(|i| pool[i]).collect()
}

pub fn run(rng: &Rng) {
    let compiler = rng.choose_str(COMPILERS);
    let opt = rng.choose_str(&["-O0","-O1","-O2","-O3"]);
    let warn_count = rng.gen_range_usize(2, 7);
    let warns: Vec<&str> = (0..warn_count).map(|_| rng.choose_str(CC_FLAGS)).collect();
    let include_count = rng.gen_range_usize(10, 25);
    let includes: Vec<&str> = (0..include_count).map(|_| rng.choose_str(KERNEL_DIRS)).collect();
    let def_count = rng.gen_range_usize(2, 5);
    let defs: Vec<&str> = (0..def_count).map(|_| rng.choose_str(CC_DEFINES)).collect();

    // Compile phase
    let num_objects = rng.gen_range_usize(30, 150);
    let mut objects: Vec<String> = Vec::with_capacity(num_objects);
    for _ in 0..num_objects {
        if should_exit() { return; }
        let dir = rng.choose_str(KERNEL_DIRS);
        let file = rng.choose_str(KERNEL_FILES);
        let obj = format!("{}/{}", dir, file);
        let mut cmd = String::new();
        cmd.push_str(compiler);
        cmd.push_str(" -c ");
        cmd.push_str(opt);
        for w in &warns { cmd.push(' '); cmd.push_str(w); }
        for inc in &includes { cmd.push_str(" -I"); cmd.push_str(inc); }
        for d in &defs { cmd.push(' '); cmd.push_str(d); }
        cmd.push_str(" -o ");
        cmd.push_str(&obj);
        print_line(&cmd);
        objects.push(obj);
        csleep(rng.gen_range_u64(20, 100));
    }

    // Link phase
    if should_exit() { return; }
    let output_name = format!("{}-{}", rng.choose_str(PACKAGE_NAMES), rng.choose_str(&["sys","lib","runner","example","tool","driver","core"]));
    let libs = pick_n(rng, PACKAGE_NAMES, rng.gen_range_usize(4, 9));
    let mut link = format!("{} -o {} ", compiler, output_name);
    for obj in &objects {
        link.push_str(obj);
        link.push(' ');
    }
    for lib in libs {
        link.push_str("-l");
        link.push_str(lib);
        link.push(' ');
    }
    print_line(&link);
    csleep(rng.gen_range_u64(200, 600));
}
EOF
