            _ if rng.bool_with_prob(0.3) => format!("RUN apt-get install -y {}", rng.choose_str(ARCH_PACKAGES)),
            _ if rng.bool_with_prob(0.3) => "COPY . /app".to_string(),
            _ if rng.bool_with_prob(0.3) => format!("WORKDIR /opt/{}", rng.alpha_string(6)),
            _ => format!("RUN {}", rng.choose_str(&[
                "apt-get update", "apt-get upgrade -y", "pip install -r requirements.txt",
                "cargo build --release", "make install", "npm install"
            ])),
        };
        print_line(&format!("Step {}/{} : {}", step, steps, cmd));
        print_line(&format!(" ---> Running in {}", rng.hex_string(12)));
        csleep(rng.gen_range_u64(200, 600));
        print_line(&format!(" ---> {}", rng.hex_string(12)));
