// Time / formatting helpers.

pub fn timestamp() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let secs = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0);
    // format HH:MM:SS of day
    let s = secs % 86400;
    let h = s / 3600;
    let m = (s % 3600) / 60;
    let sec = s % 60;
    format!("{:02}:{:02}:{:02}", h, m, sec)
}

pub fn apache_timestamp(offset_secs: i64) -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let secs = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_secs() as i64).unwrap_or(0) + offset_secs;
    // Very rough date format (we won't include exact day-of-year logic).
    // Use fixed date, just vary time.
    let (y, mo, d) = epoch_to_ymd(secs);
    let s = (secs.rem_euclid(86400)) as u64;
    let h = s / 3600;
    let m = (s % 3600) / 60;
    let sec = s % 60;
    let mon_name = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
    format!("[{:>2}/{}/{}:{:02}:{:02}:{:02} +0000]",
        d, mon_name[(mo as usize).saturating_sub(1).min(11)], y, h, m, sec)
}

// Convert epoch seconds to (year, month, day). Simple (Gregorian, proleptic after epoch).
pub fn epoch_to_ymd(epoch_secs: i64) -> (i64, u32, u32) {
    let days = epoch_secs.div_euclid(86400);
    // Epoch: 1970-01-01
    let mut y: i64 = 1970;
    let mut d = days;
    loop {
        let yd = if is_leap(y) { 366 } else { 365 };
        if d >= yd {
            d -= yd;
            y += 1;
        } else if d < 0 {
            y -= 1;
            d += if is_leap(y) { 366 } else { 365 };
        } else {
            break;
        }
    }
    let ml = month_lengths(y);
    let mut m = 1u32;
    let mut remaining = d as i64;
    for &ln in &ml {
        if remaining < ln as i64 {
            break;
        }
        remaining -= ln as i64;
        m += 1;
    }
    (y, m, remaining as u32 + 1)
}

fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}
fn month_lengths(y: i64) -> [u32; 12] {
    let f = if is_leap(y) { 29 } else { 28 };
    [31, f, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
}
