        let tool = rng.choose_str(tools);
        let dir = rng.choose_str(KERNEL_DIRS);
        let file = rng.choose_str(KERNEL_FILES);
        print_line(&format!("  {:<7} {}/{}", tool, dir, file));
        csleep(rng.gen_range_u64(20, 100));
    }
    if !should_exit() {
        print_line("  KSYM    .tmp_kallsyms1.o");
        print_line("  KSYM    .tmp_kallsyms2.o");
        print_line("  LD      vmlinux");
        print_line("  SORTEX  vmlinux");
        print_line("  SYSMAP  System.map");
        print_line("  Building modules, stage 2.");
        print_line("  Kernel: arch/x86/boot/bzImage is ready");
    }
}
