pub fn run(rng: &Rng) {
    let start: u64 = rng.gen_range_u64(0, 0xffff_ffff) << 4;
    let n = rng.gen_range_u64(100, 400);
    for i in 0..n {
        if should_exit() { return; }
        let addr = start + i * 16;
        let mut hex = String::new();
        let mut ascii = String::new();
        for _ in 0..16 {
            let b = rng.gen_range_u64(0, 256) as u8;
