mod args;
mod data;
mod duration;
mod io;
mod modules;
mod rng;
mod static_text;
mod util;

use std::time::Instant;
use std::process::ExitCode;

fn main() -> ExitCode {
    let parsed = args::parse();
    let parsed = match parsed {
        args::ParseResult::Ok(a) => a,
        args::ParseResult::Exit(code) => return ExitCode::from(code as u8),
    };

    // Setup signal handler for Ctrl+C: best effort, just print saving and exit.
    setup_signal_handler();

    if parsed.list_modules {
        args::print_list_modules();
        return ExitCode::from(0);
    }

    if parsed.print_manpage {
        static_text::print_manpage();
        return ExitCode::from(0);
    }

    if let Some(shell) = &parsed.print_completions {
        static_text::print_completions(shell);
        return ExitCode::from(0);
    }

    // Configure IO settings.
    io::set_instant_lines(parsed.instant_print_lines);
    io::set_speed_factor(parsed.speed_factor);

    let deadline = parsed.exit_after_time.as_ref().and_then(|s| {
        duration::parse_duration_msg(s).ok().map(|d| Instant::now() + d)
    });
    io::set_deadline(deadline);

    // Decide modules to run: if user specified, use those; else use all.
    let all_modules: Vec<String> = args::ALL_MODULES.iter().map(|s| s.to_string()).collect();
    let chosen: Vec<String> = if parsed.modules.is_empty() {
        all_modules.clone()
    } else {
        parsed.modules.clone()
    };

    let rng = rng::Rng::new();
    let mut modules_run: u64 = 0;

    'outer: loop {
        // Select a module at random from chosen list each iteration.
        let idx = rng.gen_range_usize(0, chosen.len());
        let name = &chosen[idx];
        modules::run_module(name, &rng);
        modules_run += 1;

        if io::should_exit() {
            break 'outer;
        }
        if let Some(limit) = parsed.exit_after_modules {
            if modules_run >= limit {
                break 'outer;
            }
        }
    }

    // Exit message.
    println!("Saving work to disk...");

    ExitCode::from(0)
}

fn setup_signal_handler() {
    use std::sync::atomic::{AtomicBool, Ordering};
    static INSTALLED: AtomicBool = AtomicBool::new(false);
    if INSTALLED.swap(true, Ordering::SeqCst) { return; }

    #[cfg(unix)]
    unsafe {
        extern "C" fn handler(_: i32) {
            crate::io::request_exit();
        }
        let mut sa: libc_sigaction = std::mem::zeroed();
        sa.sa_handler = handler as usize;
        sa.sa_flags = 0;
        sigaction_rs(2 /* SIGINT */, &sa);
        sigaction_rs(15 /* SIGTERM */, &sa);
    }
}

// A minimal wrapper around sigaction using libc via extern "C" FFI. We avoid using
// the libc crate entirely by declaring just what we need.
#[cfg(unix)]
#[repr(C)]
struct libc_sigaction {
    sa_handler: usize,
    sa_mask: [u64; 16],
    sa_flags: i32,
    sa_restorer: usize,
}

#[cfg(unix)]
unsafe fn sigaction_rs(signum: i32, act: &libc_sigaction) {
    extern "C" {
        fn sigaction(signum: i32, act: *const libc_sigaction, oldact: *mut libc_sigaction) -> i32;
    }
    sigaction(signum, act as *const _, std::ptr::null_mut());
}
